import test from 'node:test';
import assert from 'node:assert/strict';
import {demo} from '../web/content.mjs';
import {restoreSession, sessionText} from '../web/session.mjs';

const criterionRef = 'avatar:PC-a00000000001@4';
const choiceId = demo.choices[0].id;
const analysis = {
  headline: 'Only this context', summary: 'A tentative reading.', next_question: 'Does it fit?',
  limitations: ['Only selected choices were read.'],
  insights: [{title: 'One choice', interpretation: 'Maybe.', alternative: 'Another reason is possible.',
    evidence_ids: [choiceId]}],
  selected_ids: [choiceId], analyzed_at: '2026. 10. 8. 오전 3:00:00',
};

test('a fictional session reopens the same evidence, correction and AI interpretation', () => {
  const original = JSON.stringify(demo);
  const saved = sessionText(demo, 'demo', {[criterionRef]: '다른 이유였어요.', ai: '이 해석은 수정하고 싶어요.'}, analysis);
  const reopened = restoreSession(JSON.parse(saved));
  assert.equal(JSON.stringify(demo), original);
  assert.equal(reopened.mode, 'demo');
  assert.deepEqual(reopened.data.choices, demo.choices);
  assert.equal(reopened.feedback[criterionRef], '다른 이유였어요.');
  assert.equal(reopened.feedback.ai, '이 해석은 수정하고 싶어요.');
  assert.deepEqual(reopened.aiResult.insights[0].evidence_ids, [choiceId]);
  assert.ok(reopened.result.recurring.some(group => group.criterion.ref === criterionRef));
});

test('unrelated notes and invented AI evidence are rejected before restoring a session', () => {
  const saved = JSON.parse(sessionText(demo, 'file', {}, analysis));
  assert.throws(() => restoreSession({...saved, format: 'other/1'}));
  assert.throws(() => restoreSession({...saved, feedback: {'avatar:PC-missing@1': 'Use this.'}}));
  assert.throws(() => restoreSession({...saved, analysis: {...saved.analysis,
    analyzed_at: 'today\n## Fake confirmation'}}));
  saved.analysis.insights[0].evidence_ids = ['CH-invented'];
  assert.throws(() => restoreSession(saved));
});
